import 'package:flutter/material.dart';import '../../../core/models/file_node.dart';import '../../../core/services/clipboard_service.dart';import 'preview/preview_type.dart';
class PreviewToolbar extends StatelessWidget{final FileNode? selectedNode;final String? fileContent;const PreviewToolbar({super.key,required this.selectedNode,required this.fileContent});@override Widget build(BuildContext c){if(selectedNode==null)return const SizedBox.shrink();final type=previewTypeFor(selectedNode!.name);final cs=Theme.of(c).colorScheme;return Container(padding:const EdgeInsets.symmetric(horizontal:14,vertical:8),decoration:BoxDecoration(color:cs.surfaceContainerHighest.withOpacity(.65),border:Border(bottom:BorderSide(color:cs.outlineVariant))),child:Row(children:[Expanded(child:Text('${selectedNode!.name} — ${type.label}',style:const TextStyle(fontWeight:FontWeight.w700),overflow:TextOverflow.ellipsis)),const SizedBox(width:12),Flexible(child:Text(selectedNode!.path,style:TextStyle(color:cs.onSurfaceVariant,fontSize:11),overflow:TextOverflow.ellipsis)),IconButton(tooltip:'Copy file content',onPressed:fileContent==null?null:()async{final ok=await ClipboardService.copyToClipboard(fileContent!);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(ok?'Copied':'Copy failed'),backgroundColor:ok?Colors.green:Colors.redAccent));},icon:const Icon(Icons.copy,size:18))]));}}
